// Account statements (docs/ARCHITECTURE.md §7.10): requested over the API, generated by the
// worker (`generate-statement`) from the ledger, stored as CSV, then announced. Only the
// owner can see or download their statements; anyone else gets a plain 404.
import type { Queue } from 'bullmq';
import type { Currency } from '../../common/constants/currency.ts';
import {
  ConflictError,
  ErrorCode,
  NotFoundError,
  ServiceUnavailableError,
} from '../../common/errors/index.ts';
import { writeOutboxEvent } from '../../common/outbox/outbox.writer.ts';
import type { PrismaClient, Statement } from '../../generated/prisma/client.ts';
import type { DocumentStorage } from '../kyc/document-storage.ts';
import { statementCsv } from './statement.csv.ts';

const LAGOS_OFFSET_MS = 60 * 60 * 1_000;
const DAY_MS = 24 * 60 * 60 * 1_000;
/** Past this, queueing counts as failed (Redis down) and the request is refused. */
const ENQUEUE_TIMEOUT_MS = 2_000;

export interface GenerateStatementData {
  statementId: string;
}

/** `YYYY-MM-DD` Lagos dates → the UTC instants `[start, end)` that cover them. */
export function periodBounds(from: string, to: string): { start: Date; end: Date } {
  return {
    start: new Date(Date.parse(`${from}T00:00:00Z`) - LAGOS_OFFSET_MS),
    end: new Date(Date.parse(`${to}T00:00:00Z`) + DAY_MS - LAGOS_OFFSET_MS),
  };
}

const day = (date: Date) => date.toISOString().slice(0, 10);

export interface StatementView {
  id: string;
  walletId: string;
  periodStart: string;
  periodEnd: string;
  status: Statement['status'];
  openingBalance: string | null;
  closingBalance: string | null;
  entryCount: number | null;
  createdAt: string;
  completedAt: string | null;
}

function view(row: Statement): StatementView {
  return {
    id: row.id,
    walletId: row.walletId,
    periodStart: day(row.periodStart),
    periodEnd: day(row.periodEnd),
    status: row.status,
    openingBalance: row.openingBalance?.toString() ?? null,
    closingBalance: row.closingBalance?.toString() ?? null,
    entryCount: row.entryCount,
    createdAt: row.createdAt.toISOString(),
    completedAt: row.completedAt?.toISOString() ?? null,
  };
}

const notFound = () => new NotFoundError('Statement not found.');

export class StatementService {
  readonly #db: PrismaClient;
  readonly #storage: DocumentStorage;
  readonly #queue: Pick<Queue, 'add'>;
  readonly #now: () => number;

  constructor(
    db: PrismaClient,
    storage: DocumentStorage,
    queue: Pick<Queue, 'add'>,
    now: () => number = Date.now,
  ) {
    this.#db = db;
    this.#storage = storage;
    this.#queue = queue;
    this.#now = now;
  }

  /** Records the request and queues it; if the queue can't take it, nothing is kept (503). */
  async request(
    userId: string,
    input: { walletId: string; from: string; to: string },
  ): Promise<StatementView> {
    const wallet = await this.#db.wallet.findFirst({ where: { id: input.walletId, userId } });
    if (wallet === null) throw new NotFoundError('Wallet not found.');
    const row = await this.#db.statement.create({
      data: {
        userId,
        walletId: wallet.id,
        periodStart: new Date(`${input.from}T00:00:00Z`),
        periodEnd: new Date(`${input.to}T00:00:00Z`),
      },
    });
    const data: GenerateStatementData = { statementId: row.id };
    let timer: NodeJS.Timeout | undefined;
    const queued = await Promise.race([
      this.#queue
        .add('generate-statement', data, { jobId: row.id })
        .then(() => true)
        .catch(() => false),
      new Promise<false>((resolve) => {
        timer = setTimeout(() => {
          resolve(false);
        }, ENQUEUE_TIMEOUT_MS);
      }),
    ]).finally(() => {
      clearTimeout(timer);
    });
    if (!queued) {
      await this.#db.statement.delete({ where: { id: row.id } });
      throw new ServiceUnavailableError(
        'Statements are temporarily unavailable. Try again shortly.',
        {
          retryAfterSeconds: 30,
        },
      );
    }
    return view(row);
  }

  async list(userId: string, walletId?: string): Promise<StatementView[]> {
    const rows = await this.#db.statement.findMany({
      where: { userId, ...(walletId === undefined ? {} : { walletId }) },
      orderBy: { createdAt: 'desc' },
      take: 50,
    });
    return rows.map(view);
  }

  async get(userId: string, id: string): Promise<StatementView> {
    const row = await this.#db.statement.findFirst({ where: { id, userId } });
    if (row === null) throw notFound();
    return view(row);
  }

  /** The CSV and a download name; 409 until it is READY. */
  async download(userId: string, id: string): Promise<{ filename: string; content: Uint8Array }> {
    const row = await this.#db.statement.findFirst({
      where: { id, userId },
      include: { wallet: { select: { accountNumber: true } } },
    });
    if (row === null) throw notFound();
    if (row.status !== 'READY' || row.storageKey === null) {
      throw new ConflictError(
        row.status === 'FAILED'
          ? "This statement couldn't be generated. Request it again."
          : 'This statement is still being prepared.',
        { code: ErrorCode.STATEMENT_NOT_READY },
      );
    }
    return {
      filename: `fundra-statement-${row.wallet.accountNumber}-${day(row.periodStart)}-to-${day(row.periodEnd)}.csv`,
      content: await this.#storage.get(row.storageKey),
    };
  }

  /**
   * Builds the CSV from the ledger: the opening balance is the last entry's balance before the
   * period, then every entry in it with its running balance. Safe to retry: a file left by an
   * earlier attempt is replaced. On the last attempt a failure marks the statement FAILED.
   */
  async generate(statementId: string, options: { final: boolean }): Promise<'READY' | 'SKIPPED'> {
    const row = await this.#db.statement.findUnique({
      where: { id: statementId },
      include: {
        wallet: { select: { accountNumber: true, currency: true, ledgerAccountId: true } },
        user: { select: { firstName: true, lastName: true } },
      },
    });
    if (row?.status !== 'PENDING') return 'SKIPPED';
    try {
      const from = day(row.periodStart);
      const to = day(row.periodEnd);
      const { start, end } = periodBounds(from, to);
      const account = row.wallet.ledgerAccountId;
      const before = await this.#db.ledgerEntry.findFirst({
        where: { ledgerAccountId: account, createdAt: { lt: start } },
        orderBy: [{ createdAt: 'desc' }, { id: 'desc' }],
        select: { balanceAfter: true },
      });
      const entries = await this.#db.ledgerEntry.findMany({
        where: { ledgerAccountId: account, createdAt: { gte: start, lt: end } },
        orderBy: [{ createdAt: 'asc' }, { id: 'asc' }],
        include: { transaction: { select: { reference: true, type: true, description: true } } },
      });
      const openingBalance = before?.balanceAfter ?? 0n;
      const closingBalance = entries.at(-1)?.balanceAfter ?? openingBalance;
      const csv = statementCsv({
        accountName: `${row.user.firstName} ${row.user.lastName}`,
        accountNumber: row.wallet.accountNumber,
        currency: row.wallet.currency as Currency,
        periodStart: from,
        periodEnd: to,
        openingBalance,
        closingBalance,
        lines: entries.map((e) => ({
          at: e.createdAt,
          reference: e.transaction.reference,
          type: e.transaction.type,
          description: e.transaction.description,
          direction: e.direction,
          amount: e.amount,
          balanceAfter: e.balanceAfter ?? 0n,
        })),
      });
      const key = `${row.userId}/${row.id}`;
      await this.#storage.delete(key);
      await this.#storage.put(key, new TextEncoder().encode(csv));
      await this.#db.$transaction(async (tx) => {
        await tx.statement.update({
          where: { id: row.id },
          data: {
            status: 'READY',
            storageKey: key,
            openingBalance,
            closingBalance,
            entryCount: entries.length,
            completedAt: new Date(this.#now()),
          },
        });
        await writeOutboxEvent(tx, {
          type: 'statement.ready',
          aggregate: { type: 'statement', id: row.id },
          payload: { statementId: row.id, userId: row.userId, periodStart: from, periodEnd: to },
        });
      });
      return 'READY';
    } catch (err) {
      if (options.final) {
        await this.#db.statement.update({
          where: { id: statementId },
          data: {
            status: 'FAILED',
            failureReason: (err instanceof Error ? err.message : String(err)).slice(0, 500),
          },
        });
      }
      throw err;
    }
  }
}
